import XCTest

final class TapOpenUITests: XCTestCase {
    func testTapOpenOnDialog() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        var tapped = false

        let alertOpen = springboard.alerts.buttons["Open"]
        if alertOpen.waitForExistence(timeout: 15) {
            alertOpen.tap()
            tapped = true
        }

        if !tapped {
            let anyOpen = springboard.buttons["Open"].firstMatch
            if anyOpen.waitForExistence(timeout: 5) {
                anyOpen.tap()
                tapped = true
            }
        }

        XCTAssertTrue(tapped, "Could not find or tap the Open button")
        Thread.sleep(forTimeInterval: 5)
    }
}

import XCTest

final class TapOpenUITests: XCTestCase {
    func testDismissAndLoadApp() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        let cancel = springboard.alerts.buttons["Cancel"]
        if cancel.waitForExistence(timeout: 5) {
            cancel.tap()
        }

        XCTAssertTrue(app.waitForState(.runningForeground, timeout: 10), "Bluesky app not in foreground")

        let serverRow = app.staticTexts["http://localhost:8081"].firstMatch
        XCTAssertTrue(serverRow.waitForExistence(timeout: 15), "Dev server row not found")
        serverRow.tap()

        let following = app.staticTexts["Following"].firstMatch
        XCTAssertTrue(following.waitForExistence(timeout: 90), "Following feed did not load")
        Thread.sleep(forTimeInterval: 2)
    }

    func testTapOpen() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        var tapped = false

        let alertOpen = springboard.alerts.buttons["Open"]
        if alertOpen.waitForExistence(timeout: 15) {
            alertOpen.tap()
            tapped = true
        }

        if !tapped {
            let anyOpen = springboard.buttons["Open"].firstMatch
            if anyOpen.waitForExistence(timeout: 5) {
                anyOpen.tap()
                tapped = true
            }
        }

        XCTAssertTrue(tapped, "Could not find or tap the Open button")
        Thread.sleep(forTimeInterval: 4)
    }
}
